package ch.jalu.configme.configurationdata;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public class CommentsConfigurationTest {

    @Test
    public void newCommentsConfiguration_isInitializedCorrectly() {
        CommentsConfiguration config = new CommentsConfiguration();
        assertNotNull(config.getAllComments());
    }

    @Test
    public void newCommentsConfiguration_isInitializedWithEmptyMap() {
        CommentsConfiguration config = new CommentsConfiguration();
        assertEquals(0, ((HashMap) config.getAllComments()).size());
    }

    @Test
    public void newCommentsConfiguration_canBeInitializedFromMap() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("path", Arrays.asList("comment1"));
        CommentsConfiguration config = new CommentsConfiguration(comments);
        assertEquals(1, ((HashMap) config.getAllComments()).size());
    }

    @Test
    public void setComment_setsNewLinesForPath() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration config = new CommentsConfiguration(comments);
        String path = "path";
        String commentLine = "comment line";
        config.setComment(path, commentLine);
        assertEquals(1, ((HashMap) config.getAllComments()).get(path).size());
    }

    @Test
    public void setComment_setsNewLinesForMultiplePaths() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration config = new CommentsConfiguration(comments);
        String path1 = "path1";
        String commentLine1 = "comment line 1";
        String path2 = "path2";
        String commentLine2 = "comment line 2";
        config.setComment(path1, commentLine1, commentLine2);
        assertEquals(2, ((HashMap) config.getAllComments()).size());
    }

    @Test
    public void setComment_setsSingleLineWithoutCommentMarker() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration config = new CommentsConfiguration(comments);
        String path = "path";
        String commentLine = "";
        config.setComment(path, commentLine);
        assertEquals(1, ((HashMap) config.getAllComments()).get(path).size());
    }

    @Test
    public void getAllComments_returnsUnmodifiableMap() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration config = new CommentsConfiguration(comments);
        @NotNull Map<String, @UnmodifiableView List<String>> result = config.getAllComments();
        assertTrue(result instanceof UnmodifiableMap);
    }

    @Test
    public void getAllComments_returnsEmptyListForEmptyPath() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration config = new CommentsConfiguration(comments);
        @NotNull Map<String, @UnmodifiableView List<String>> result = config.getAllComments();
        assertEquals(0, ((HashMap) result).get(""));
    }

}
